-- Seguimiento RRHH para instalaciones nuevas. Para actualizar una base existente: npm run db:workflow.

CREATE TABLE NOM_RH_EVENTO (RHE_ID NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, RHE_FECHA TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, RHE_ENTIDAD VARCHAR2(60) NOT NULL, RHE_REGISTRO NUMBER NOT NULL, EML_ID NUMBER, RHE_ACCION VARCHAR2(60) NOT NULL, RHE_ACTOR VARCHAR2(200) NOT NULL, RHE_VERIFICADO NUMBER(1) DEFAULT 0 NOT NULL, RHE_MOTIVO VARCHAR2(2000), RHE_EFECTIVA DATE, RHE_ANTES CLOB, RHE_DESPUES CLOB);

CREATE TABLE NOM_RH_REVISION (NOM_ID NUMBER NOT NULL REFERENCES NOM_NOMINA(NOM_ID), RHR_FUENTE VARCHAR2(60) NOT NULL, RHR_REGISTRO NUMBER NOT NULL, RHR_HUELLA VARCHAR2(64) NOT NULL, RHR_DECISION VARCHAR2(20) NOT NULL, RHR_MOTIVO VARCHAR2(2000) NOT NULL, NDC_ID NUMBER REFERENCES NOM_NOMINA_CONCEPTO(NDC_ID), CONSTRAINT PK_NOM_RH_REVISION PRIMARY KEY(NOM_ID,RHR_FUENTE,RHR_REGISTRO));

CREATE TABLE NOM_RH_VACACION (VAC_ID NUMBER PRIMARY KEY REFERENCES NOM_VACACION(VAC_ID), RHV_DIAS NUMBER(8,2) NOT NULL, RHV_SALDO NUMBER(8,2) NOT NULL, RHV_FUENTE VARCHAR2(1000) NOT NULL, RHV_FECHA TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, RHV_CALCULO CLOB);

CREATE TABLE NOM_RH_PAGO_LIQ (RPL_ID NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, LIL_ID NUMBER NOT NULL REFERENCES NOM_LIQUIDACION_LABORAL(LIL_ID), CBE_ID NUMBER NOT NULL REFERENCES NOM_CUENTA_BANCARIA_EMPLEADO(CBE_ID), RPL_FECHA DATE NOT NULL, RPL_MONTO NUMBER(14,2) NOT NULL CHECK(RPL_MONTO>0), RPL_REFERENCIA VARCHAR2(200) NOT NULL, RPL_ESTADO VARCHAR2(20) DEFAULT 'CONFIRMADA' NOT NULL CHECK(RPL_ESTADO IN ('CONFIRMADA','ANULADA')), CONSTRAINT UQ_NOM_RH_PAGO_REF UNIQUE(LIL_ID,RPL_REFERENCIA));
